		expect(() => checkEventAuthWithoutState(create, [])).not.toThrow();
	});

	it("should allow the room creator's first join in a v11 room", async () => {
		const create = new FakeStateEventCreator()
			.asRoomCreate()
			.withRoomId(roomId)
			.withSender(creator)
			.withContent({ room_version: '11' })
