import { describe, expect, it } from 'bun:test';

import { getErrorMessage } from './get-error-message';

describe('getErrorMessage', () => {
	it('should return the message from an Error object', () => {
		const error = new Error('Test error message');

		expect(getErrorMessage(error)).toBe('Test error message');
	});

	it('should handle custom Error classes', () => {
		class CustomError extends Error {
			constructor(message: string) {
				super(message);
				this.name = 'CustomError';
			}
		}

		const error = new CustomError('Custom error message');

		expect(getErrorMessage(error)).toBe('Custom error message');
	});

	it('should use the string directly if error is a string', () => {
		const errorString = 'Error as a string';

		expect(getErrorMessage(errorString)).toBe('Error as a string');
	});

	it('should stringify objects', () => {
		const errorObject = { code: 500, message: 'Internal Server Error' };

		expect(getErrorMessage(errorObject)).toBe(JSON.stringify(errorObject));
	});

	it('should return "Unknown error" for null', () => {
		expect(getErrorMessage(null)).toBe('Unknown error');
	});

	it('should return "Unknown error" for undefined', () => {
		expect(getErrorMessage(undefined)).toBe('Unknown error');
	});

	it('should return "Unknown error" for non-error values', () => {
		expect(getErrorMessage(123)).toBe('Unknown error');
		expect(getErrorMessage(true)).toBe('Unknown error');
	});
});

import { describe, expect, it } from 'bun:test';

import { PersistentEventFactory } from '@rocket.chat/federation-room';

import { getEventSchemaForType } from './event-schemas';

const base = {
	room_id: '!room:hs1',
	sender: '@admin:hs1',
	origin_server_ts: 1733107418719,
	depth: 1,
	prev_events: [],
	auth_events: [],
};

const createEvent = { ...base, type: 'm.room.create', state_key: '' };
const redaction = { ...base, type: 'm.room.redaction' };
const target = '$8ftnUd9WTPTQGbdPgfOPea8bOEQ21qPvbcGqeOApQxA';
const otherTarget = '$AAAnUd9WTPTQGbdPgfOPea8bOEQ21qPvbcGqeOApQxA';

function validate(event: object, roomVersion: string) {
	return getEventSchemaForType((event as { type: string }).type, roomVersion).safeParse(event).success;
}

describe('event schemas', () => {
	it('requires m.room.create content.creator before v11', () => {
		expect(validate({ ...createEvent, content: { room_version: '10', creator: '@admin:hs1' } }, '10')).toBe(true);
		expect(validate({ ...createEvent, content: { room_version: '10' } }, '10')).toBe(false);
	});

	it('does not require m.room.create content.creator from v11 on', () => {
		expect(validate({ ...createEvent, content: { room_version: '11' } }, '11')).toBe(true);
	});

	it('takes the redaction target from the top level before v11', () => {
		expect(validate({ ...redaction, redacts: target, content: {} }, '10')).toBe(true);
		expect(validate({ ...redaction, content: { redacts: target } }, '10')).toBe(false);
	});

	it('takes the redaction target from content from v11 on', () => {
		expect(validate({ ...redaction, content: { redacts: target } }, '11')).toBe(true);
		expect(validate({ ...redaction, redacts: target, content: {} }, '11')).toBe(false);
	});

	// rejecting this would mean dropping an event the rest of the federation accepted, so a v11
	// redaction carrying the legacy top level field is accepted and the field ignored
	it('tolerates a legacy top level redacts in v11 and resolves the target from content', () => {
		const withBoth = { ...redaction, redacts: otherTarget, content: { redacts: target } };

		expect(validate(withBoth, '11')).toBe(true);

		expect(PersistentEventFactory.createFromRawEvent(withBoth as never, '11').getRedacts()).toBe(target);
	});

	it('resolves a schema for every supported room version', () => {
		for (const roomVersion of PersistentEventFactory.supportedRoomVersions) {
			// creator is required before v11 and dropped from v11 on
			const content = Number(roomVersion) < 11 ? { room_version: roomVersion, creator: '@admin:hs1' } : { room_version: roomVersion };

			expect(validate({ ...createEvent, content }, roomVersion)).toBe(true);
		}
	});

	it('falls back to the permissive base schema for unknown event types', () => {
		expect(validate({ ...base, type: 'com.example.custom', content: { anything: true } }, '11')).toBe(true);
	});
});

import { afterAll, afterEach, beforeEach, describe, expect, it, mock, spyOn } from 'bun:test';

import * as core from '@rocket.chat/federation-core';
import * as nacl from 'tweetnacl';

import type { ConfigService } from './config.service';
import { FederationRequestService } from './federation-request.service';

describe('FederationRequestService', async () => {
	let service: FederationRequestService;
	let configService: ConfigService;

	const mockServerName = 'example.com';
	const mockSigningKey = 'aGVsbG93b3JsZA==';
	const mockSigningKeyId = 'ed25519:1';

	const mockKeyPair = {
		publicKey: new Uint8Array([1, 2, 3]),
		secretKey: new Uint8Array([4, 5, 6]),
	};

	const mockDiscoveryResult = [
		'https://target.example.com:443' as const,
		{
			Host: 'target.example.com',
		},
	];

	const { getHomeserverFinalAddress } = await import('../server-discovery/discovery');

	const { fetch: originalFetch } = await import('@rocket.chat/federation-core');

	await mock.module('../server-discovery/discovery', () => ({
		getHomeserverFinalAddress: () => mockDiscoveryResult,
	}));

	await mock.module('@rocket.chat/federation-core', () => ({
		fetch: async (_url: string, _options?: RequestInit) => {
			return {
				ok: true,
				status: 200,
				json: async () => ({ result: 'success' }),
				text: async () => '{"result":"success"}',
				multipart: async () => null,
			} as Response;
		},
	}));

	afterAll(() => {
		mock.restore();
		mock.module('../server-discovery/discovery', () => ({
			getHomeserverFinalAddress,
		}));
		mock.module('@rocket.chat/federation-core', () => ({
			fetch: originalFetch,
		}));
	});

	const mockSignature = new Uint8Array([7, 8, 9]);

	const mockSignedJson = {
		content: 'test',
		signatures: {
			'example.com': {
				'ed25519:1': 'abcdef',
			},
		},
	};

	const mockAuthHeaders = 'X-Matrix origin="example.com",destination="target.example.com",key="ed25519:1",sig="xyz123"';

	beforeEach(() => {
		spyOn(nacl.sign.keyPair, 'fromSecretKey').mockReturnValue(mockKeyPair);
		spyOn(nacl.sign, 'detached').mockReturnValue(mockSignature);

		spyOn(core, 'extractURIfromURL').mockReturnValue('/test/path?query=value');
		spyOn(core, 'authorizationHeaders').mockResolvedValue(mockAuthHeaders);
		spyOn(core, 'signJson').mockResolvedValue(mockSignedJson);
		spyOn(core, 'computeAndMergeHash').mockImplementation((obj: unknown) => obj);

		configService = {
			getConfig: (key: string) => {
				if (key === 'serverName') {
					return mockServerName;
				}
				throw new Error(`Unknown config key: ${key}`);
			},
			serverName: mockServerName,
			getSigningKeyBase64: async () => mockSigningKey,
			getSigningKeyId: async () => mockSigningKeyId,
		} as ConfigService;

		service = new FederationRequestService(configService);
	});

	afterEach(() => {
		mock.restore();
	});

	describe('makeSignedRequest', () => {
		it('should make a successful signed request without body', async () => {
			const fetchSpy = spyOn(core, 'fetch');

			const result = await service.makeSignedRequest({
				method: 'GET',
				domain: 'target.example.com',
				uri: '/test/path',
			});

			expect(configService.serverName).toBe(mockServerName);
			expect(await configService.getSigningKeyBase64()).toBe(mockSigningKey);
			expect(await configService.getSigningKeyId()).toBe(mockSigningKeyId);
			expect(configService.serverName).toBe(mockServerName);
			expect(await configService.getSigningKeyBase64()).toBe(mockSigningKey);
			expect(await configService.getSigningKeyId()).toBe(mockSigningKeyId);

			expect(nacl.sign.keyPair.fromSecretKey).toHaveBeenCalled();

			expect(fetchSpy).toHaveBeenCalledWith(
				new URL('https://target.example.com/test/path'),
				expect.objectContaining({
					method: 'GET',
					headers: expect.objectContaining({
						Authorization: [REDACTED],
						Host: 'target.example.com',
					}),
				}),
			);

			expect(result.ok).toBe(true);
			expect(result.status).toBe(200);
			expect(await result.json()).toEqual({ result: 'success' });
		});

		it('should make a successful signed request with body', async () => {
			const fetchSpy = spyOn(core, 'fetch');

			const mockBody = { key: 'value' };

			const result = await service.makeSignedRequest({
				method: 'POST',
				domain: 'target.example.com',
				uri: '/test/path',
				body: mockBody,
			});

			expect(core.signJson).toHaveBeenCalledWith(
				expect.objectContaining({ key: 'value', signatures: {} }),
				expect.any(Object),
				mockServerName,
			);

			expect(core.authorizationHeaders).toHaveBeenCalledWith(
				mockServerName,
				expect.any(Object),
				'target.example.com',
				'POST',
				'/test/path?query=value',
				mockSignedJson,
			);

			expect(fetchSpy).toHaveBeenCalledWith(
				new URL('https://target.example.com/test/path'),
				expect.objectContaining({
					method: 'POST',
					body: JSON.stringify(mockSignedJson),
