type OUTPUT = [`https://${string}:${string | number}`, { Host: string }];

/*
 * 1. If the hostname is an IP literal, then that IP address should be used, together with the given port number, or 8448 if no port is given. The target server must present a valid certificate for the IP address. The Host header in the request should be set to the server name, including the port if the server name included one.
 */

function spec_1__1(): [INPUT[], OUTPUT[]] {
	return [
		['11.0.0.1', '11.0.0.1:45'],
		[
			['https://11.0.0.1:8448' as const, { Host: '11.0.0.1' }],
			['https://11.0.0.1:45' as const, { Host: '11.0.0.1:45' }],
		],
	];
}

function spec_1__2(): [INPUT[], OUTPUT[]] {
	return [
		['[::1]', '[::1]:45'],
		[
			['https://[::1]:8448' as const, { Host: '[::1]' }],
			['https://[::1]:45' as const, { Host: '[::1]:45' }],
		],
	];
}

/*
 * SPEC:
 * 2. If the hostname is not an IP literal, and the server name includes an explicit port, resolve the hostname to an IP address using CNAME, AAAA or A records. Requests are made to the resolved IP address and given port with a Host header of the original server name (with port). The target server must present a valid certificate for the hostname.
 */

function spec_2__1(): [INPUT[], OUTPUT[]] {
	stubs.resolveHostname.resolves('11.0.0.1');
	return [['example.com:45'], [['https://11.0.0.1:45' as const, { Host: 'example.com:45' }]]];
}

function spec_2__2(): [INPUT[], OUTPUT[]] {
	stubs.resolveHostname.resolves('[::1]');
	return [['example_spec_2__2.com:45'], [['https://[::1]:45' as const, { Host: 'example_spec_2__2.com:45' }]]];
}

// wellknown
// If <delegated_hostname> is an IP literal, then that IP address should be used together with the <delegated_port> or 8448 if no port is provided. The target server must present a valid TLS certificate for the IP address. Requests must be made with a Host header containing the IP address, including the port if one was provided.
function spec_3_1__1(): [INPUT[], OUTPUT[]] {
	// If the hostname is not an IP literal and no port is provided
	const inputs = ['example_spec_3_1__1.com'];

	stubs.resolveHostname.resolves('11.0.0.1');

	// Mock the .well-known response
	stubs.fetch.resolves({
		ok: true,
		json: () => Promise.resolve({ 'm.server': '11.0.0.1:45' }),
		headers: new Headers({
			'cache-control': 'max-age=3600',
		}),
	});

	return [inputs, [['https://11.0.0.1:45' as const, { Host: '11.0.0.1:45' }]]];
}

function spec_3_1__2(): [INPUT[], OUTPUT[]] {
	const inputs = ['example_spec_3_1__2.com'];

	stubs.resolveHostname.resolves('[::1]');

	stubs.fetch.resolves({
		ok: true,
		json: () => Promise.resolve({ 'm.server': '[::1]:45' }),
	});

	return [inputs, [['https://[::1]:45' as const, { Host: '[::1]:45' }]]];
}

/* 3.2. If <delegated_hostname> is not an IP literal, and <delegated_port> is present, an IP address is discovered by looking up CNAME, AAAA or A records for <delegated_hostname>. The resulting IP address is used, alongside the <delegated_port>. Requests must be made with a Host header of <delegated_hostname>:<delegated_port>. The target server must present a valid certificate for <delegated_hostname>.
 */
function spec_3_2(): [INPUT[], OUTPUT[]] {
	const inputs = ['example_spec_3_2.com'];

	stubs.resolveHostname.reset();

	// for some reason onFirstCall and onSecondCall is not working
	stubs.resolveHostname.callsFake((hostname: string) => {
		if (hostname === 'example_spec_3_2.com') {
			return Promise.resolve('11.0.0.1');
		}

		if (hostname === 'example2_spec_3_2.com') {
			return Promise.resolve('[::1]');
		}
	});

	stubs.fetch.resolves({
		ok: true,
		json: () => Promise.resolve({ 'm.server': 'example2_spec_3_2.com:45' }), // delegatedPort is present
	});

	return [inputs, [['https://[::1]:45' as const, { Host: 'example2_spec_3_2.com:45' }]]];
}

/* If <delegated_hostname> is not an IP literal and no <delegated_port> is present, an SRV record is looked up for _matrix-fed._tcp.<delegated_hostname>. This may result in another hostname (to be resolved using AAAA or A records) and port. Requests should be made to the resolved IP address and port with a Host header containing the <delegated_hostname>. The target server must present a valid certificate for <delegated_hostname>.*/
function spec_3_3__1(): [INPUT[], OUTPUT[]] {
	const inputs = ['example_spec_3_3__1.com'];

	stubs.resolveHostname.resolves('11.0.0.1');

	stubs.fetch.resolves({
		ok: true,
		json: () => Promise.resolve({ 'm.server': 'example2_spec_3_3__1.com' }), // no delegatedPort is present, delegatedHostname is present and not ip
	});

	stubs.resolveSrv.resolves([{ name: '::1', port: 45 }]);

	return [inputs, [['https://[::1]:45' as const, { Host: 'example2_spec_3_3__1.com' }]]];
}

function spec_3_3__2(): [INPUT[], OUTPUT[]] {
	const inputs = ['example_spec_3_3__2.com'];

	stubs.resolveHostname.callsFake((name) => {
		if (name === 'exmaple_spec_3_3__2.com') return '11.0.0.1';

		if (name === 'example3_spec_3_3__2.com') return '[::1]';
	});

	stubs.fetch.resolves({
		ok: true,
		json: () => Promise.resolve({ 'm.server': 'example2_spec_3_3__2.com' }), // no delegatedPort is present, delegatedHostname is present and not ip
	});

	stubs.resolveSrv.resolves([{ name: 'example3_spec_3_3__2.com', port: 45 }]); // another hostname
	// now should do another resolveHostname

	return [inputs, [['https://[::1]:45' as const, { Host: 'example2_spec_3_3__2.com' }]]];
}

/* If the /.well-known request returned an error response, and no SRV records were found, an IP address is resolved using CNAME, AAAA and A records. Requests are made to the resolved IP address using port 8448 and a Host header containing the <hostname>. The target server must present a valid certificate for <hostname>. */
function spec_3_4__1(): [INPUT[], OUTPUT[]] {
	const inputs = ['example_spec_3_4__1.com'];

	stubs.resolveHostname.resolves('11.0.0.1');

	// wellknown no
	stubs.fetch.resolves({
		ok: false,
	});

	// srv no
	stubs.resolveSrv.resolves([]);

	return [inputs, [['https://11.0.0.1:8448' as const, { Host: 'example_spec_3_4__1.com' }]]];
}

async function runTest(inputs: INPUT[], outputs: OUTPUT[]) {
	for (let i = 0; i < inputs.length; i++) {
		const input = inputs[i];
		const output = outputs[i];

		// eslint-disable-next-line no-await-in-loop
		const [address, headers] = await getHomeserverFinalAddress(input);

		expect(address).toBe(output[0]);
		expect(headers).toEqual(output[1]);
	}
}

describe('_URL', () => {
	it('should mention port if specified even if standard port is used, unlike node:url', () => {
		const url = new _URL('https://example.com:443');
		expect(url.port).toBe('443');
		expect(url.origin).toBe('https://example.com');
	});

	it('should not mention port if not specified, like node:url', () => {
		const url = new _URL('https://example.com');
		expect(url.port).toBe('');
		expect(url.origin).toBe('https://example.com');
	});

	it('should parse url without protocol part', () => {
		const url = new _URL('example.com');
		expect(url.origin).toBe('https://example.com');
	});
});

describe('[Server Discovery 2.1 - resolve final address] https://spec.matrix.org/v1.12/server-server-api/#resolving-server-names', () => {
	it('2.1.1 (ipv4)', async () => {
		return runTest(...spec_1__1());
	});
	it('2.1.1 (ipv6)', async () => {
		return runTest(...spec_1__2());
	});
	it('2.1.2 (ipv4)', async () => {
		return runTest(...spec_2__1());
	});
	it('2.1.2 (ipv6)', async () => {
		return runTest(...spec_2__2());
	});
	it('3.1.1 (well-known delegation - ip4)', async () => {
		return runTest(...spec_3_1__1());
	});
	it('3.1.1 (well-known delegation - ip6)', async () => {
		return runTest(...spec_3_1__2());
	});
	it('3.2.1 (well-known delegation)', async () => {
		return runTest(...spec_3_2());
	});
	it('3.3.1 (well-known delegation)', async () => {
		return runTest(...spec_3_3__1());
	});
	it('3.3.2 (well-known delegation)', async () => {
		return runTest(...spec_3_3__2());
	});
	it('3.4.1 (well-known delegation - no wellknown, no srv)', async () => {
		return runTest(...spec_3_4__1());
	});
});

import { beforeAll, describe, expect, it } from 'bun:test';

import type {
	PduJoinRuleEventContent,
	PduPowerLevelsEventContent,
	PersistentEventBase,
	RoomVersion,
	StateMapKey,
	UserID,
} from '@rocket.chat/federation-room';
import { container } from 'tsyringe';

import { FederationValidationService, federationSDK, init } from '..';
import { AppConfig, ConfigService } from './config.service';
import { RoomService } from './room.service';
import { StateService } from './state.service';

describe('RoomService', async () => {
	if (!process.env.RUN_MONGO_TESTS) {
		console.warn('Skipping tests that require a database');
		return;
	}

	beforeAll(async () => {
		const databaseConfig = {
			uri: process.env.MONGO_URI || 'mongodb://localhost:27017?directConnection=true',
			name: 'matrix_test',
			poolSize: 100,
		};

		await init({
			dbConfig: databaseConfig,
		});

		federationSDK.setConfig({
			signingKey: '',
			serverName: 'example.com',
		} as AppConfig);
	});

	const configService = new ConfigService();

	container.register(ConfigService, {
		useValue: configService,
	});

	// dont validate anything during tests
	container.register(FederationValidationService, {
		useValue: {
			async validateOutboundUser() {
				return true;
			},
			async validateOutboundInvite() {
				return true;
			},
		} as unknown as FederationValidationService,
	});

	const stateService = container.resolve(StateService);
	const roomService = container.resolve(RoomService);

	const createRoom = async (
		username: UserID,
		joinRule: PduJoinRuleEventContent['join_rule'],
		{
			users = {},
			events = {},
		}: {
			users?: PduPowerLevelsEventContent['users'];
			events?: PduPowerLevelsEventContent['events'];
		} = {
			users: {},
			events: {},
		},
	) => {
		const result = await federationSDK.createRoom(username, 'Test Room', joinRule, {
			users,
			events,
		});

		const state = await stateService.getLatestRoomState(result.room_id);

		const memberKey = [...state.keys()].find((stateKey) => stateKey.includes('m.room.member:')) as `m.room.member:${string}`;

		const roomCreateEvent = state.get('m.room.create:');
		const joinRuleEvent = state.get('m.room.join_rules:');
		const powerLevelEvent = state.get('m.room.power_levels:');
		const creatorMembershipEvent = state.get(memberKey);
		const roomNameEvent = state.get('m.room.name:');

		if (!roomCreateEvent || !joinRuleEvent || !powerLevelEvent || !creatorMembershipEvent || !roomNameEvent) {
			throw new Error('Event not found');
		}

		return {
			roomCreateEvent,
			joinRuleEvent,
			powerLevelEvent,
			creatorMembershipEvent,
			roomNameEvent,
		} as {
			roomCreateEvent: PersistentEventBase<RoomVersion, 'm.room.create'>;
			joinRuleEvent: PersistentEventBase<RoomVersion, 'm.room.join_rules'>;
			powerLevelEvent: PersistentEventBase<RoomVersion, 'm.room.power_levels'>;
			creatorMembershipEvent: PersistentEventBase<RoomVersion, 'm.room.member'>;
			roomNameEvent: PersistentEventBase<RoomVersion, 'm.room.name'>;
		};
	};

	describe('createRoom', () => {
		it('should create room correctly', async () => {
			const username = '@alice:example.com' as UserID;
			const { roomCreateEvent, roomNameEvent, joinRuleEvent, powerLevelEvent, creatorMembershipEvent } = await createRoom(
				username,
				'public',
			);

			const { roomId } = roomCreateEvent;

			const state = await stateService.getLatestRoomState(roomId);

			// check each event
			expect(state.get(roomCreateEvent.getUniqueStateIdentifier())).toHaveProperty('eventId', roomCreateEvent.eventId);
			expect(state.get(roomNameEvent.getUniqueStateIdentifier())).toHaveProperty('eventId', roomNameEvent.eventId);
			expect(state.get(joinRuleEvent.getUniqueStateIdentifier())).toHaveProperty('eventId', joinRuleEvent.eventId);
			expect(state.get(powerLevelEvent.getUniqueStateIdentifier())).toHaveProperty('eventId', powerLevelEvent.eventId);
			expect(state.get(creatorMembershipEvent.getUniqueStateIdentifier())).toHaveProperty('eventId', creatorMembershipEvent.eventId);

			expect([...state.keys()]).toEqual(
				expect.arrayContaining([
					'm.room.canonical_alias:',
					'm.room.create:',
					'm.room.name:',
					'm.room.join_rules:',
					'm.room.power_levels:',
					`m.room.member:${username}`,
				]),
			);
		});

		it('should always keep the owner as 100', async () => {
			const username = '@alice:example.com' as UserID;
			const { powerLevelEvent } = await createRoom(username, 'public', {
				users: { '@alice:example.com': 10 },
			});

			expect(powerLevelEvent.getContent().users[username]).toBe(100);
		});

		it('should accept custom event powers', async () => {
			const username = '@alice:example.com' as UserID;
			const { powerLevelEvent } = await createRoom(username, 'public', {
				events: { 'rc.room.name': 10 },
			});
			expect(powerLevelEvent.getContent().events['rc.room.name']).toBe(10);
		});

		it.skip('should create direct message room correctly', async () => {
			const username = '@alice:example.com' as UserID;
			const targetUsername = '@bob:example.com' as UserID;

			const roomId = await federationSDK.createDirectMessageRoom(username, targetUsername);

			const state = await stateService.getLatestRoomState(roomId);

			expect(state.size).toBe(2);

			expect([...state.keys()]).toEqual(
				expect.arrayContaining(['m.room.create:', `m.room.member:${targetUsername}`, `m.room.member:${username}`]),
			);
		});
	});

	describe('joinUser', () => {
		it('should join user to room correctly', async () => {
			const username = '@alice:example.com' as UserID;
			const secondaryUsername = '@bob:example.com' as UserID;
			const { roomCreateEvent } = await createRoom(username, 'public');

			const { roomId } = roomCreateEvent;

			const initialState = await stateService.getLatestRoomState(roomId);

			const imtialStateKeys = [...initialState.keys()].sort();

			const expectedStateKeys = [
				'm.room.create:',
				`m.room.member:${username}`,
				'm.room.join_rules:',
				'm.room.power_levels:',
				'm.room.name:',
				'm.room.canonical_alias:',
			].sort() as StateMapKey[];

			expect(imtialStateKeys).toEqual(expectedStateKeys);

			await roomService.joinUser(roomId, secondaryUsername);

			const state = await stateService.getLatestRoomState(roomId);

			expect([...state.keys()]).toEqual(
				expect.arrayContaining(['m.room.create:', `m.room.member:${username}`, `m.room.member:${secondaryUsername}`]),
			);
		});
	});

	describe('leaveRoom', () => {
		it('should leave user from room correctly', async () => {
			const username = '@alice:example.com' as UserID;
			const { roomCreateEvent } = await createRoom(username, 'public');

			const { roomId } = roomCreateEvent;

			await federationSDK.leaveRoom(roomId, username);

			const state = await stateService.getLatestRoomState(roomId);

			expect([...state.keys()]).toEqual(expect.arrayContaining(['m.room.create:', `m.room.member:${username}`]));

			const userState = state.get(`m.room.member:${username}`) as PersistentEventBase<RoomVersion, 'm.room.member'>;

			expect(userState?.getContent().membership).toBe('leave');
		});
	});

	describe('kickUser', () => {
		it('should ban user to room correctly', async () => {
			const username = '@alice:example.com' as UserID;
			const secondaryUsername = '@bob:example.com' as UserID;
			const { roomCreateEvent } = await createRoom(username, 'public');

			const { roomId } = roomCreateEvent;

			await federationSDK.kickUser(roomId, secondaryUsername, username);

			const state = await stateService.getLatestRoomState(roomId);

			expect([...state.keys()]).toEqual(
				expect.arrayContaining(['m.room.create:', `m.room.member:${username}`, `m.room.member:${secondaryUsername}`]),
			);

			const secondaryState = state.get(`m.room.member:${secondaryUsername}`) as PersistentEventBase<RoomVersion, 'm.room.member'>;

			expect(secondaryState?.getContent().membership).toBe('leave');
		});
	});

	describe('banUser', () => {
		it('should ban user to room correctly', async () => {
			const username = '@alice:example.com' as UserID;
			const secondaryUsername = '@bob:example.com' as UserID;
			const { roomCreateEvent } = await createRoom(username, 'public');

			const { roomId } = roomCreateEvent;
			await federationSDK.banUser(roomId, secondaryUsername, username);

			const state = await stateService.getLatestRoomState(roomId);

			expect([...state.keys()]).toEqual(
				expect.arrayContaining(['m.room.create:', `m.room.member:${username}`, `m.room.member:${secondaryUsername}`]),
			);

			const secondaryState = state.get(`m.room.member:${secondaryUsername}`) as PersistentEventBase<RoomVersion, 'm.room.member'>;

			expect(secondaryState?.getContent().membership).toBe('ban');
		});
	});

	describe('updateUserPowerLevel', () => {
		it('should update user power level correctly', async () => {
			const username = '@alice:example.com' as UserID;
			const secondaryUsername = '@bob:example.com' as UserID;
			const { roomCreateEvent } = await createRoom(username, 'public');

			const { roomId } = roomCreateEvent;

			await roomService.joinUser(roomId, username, secondaryUsername);

			expect(
				await stateService.getLatestRoomState(roomId).then((state) => {
					return state.get('m.room.power_levels:')!.getContent();
				}),
			).toHaveProperty('users', {
				[username]: 100,
			});

			await federationSDK.updateUserPowerLevel(roomId, secondaryUsername, 50, username);

			expect(
				await stateService.getLatestRoomState(roomId).then((state) => {
					return state.get('m.room.power_levels:')!.getContent();
				}),
			).toHaveProperty('users', {
				[username]: 100,
				[secondaryUsername]: 50,
			});
		});
	});

	describe('acceptInvite', () => {
		it('should accept invite and join user to room correctly', async () => {
			const username = '@alice:example.com' as UserID;
			const invitedUsername = '@bob:example.com' as UserID;
			const { roomCreateEvent } = await createRoom(username, 'invite');
			const { roomId } = roomCreateEvent;

			await federationSDK.inviteUserToRoom(invitedUsername, roomId, username);

			const stateBeforeAccept = await stateService.getLatestRoomState(roomId);
			const inviteMemberEvent = stateBeforeAccept.get(`m.room.member:${invitedUsername}`) as
				| PersistentEventBase<RoomVersion, 'm.room.member'>
				| undefined;

			expect(inviteMemberEvent?.getContent().membership).toBe('invite');

			await federationSDK.acceptInvite(roomId, invitedUsername);

			const stateAfterAccept = await stateService.getLatestRoomState(roomId);
			const joinMemberEvent = stateAfterAccept.get(`m.room.member:${invitedUsername}`) as PersistentEventBase<RoomVersion, 'm.room.member'>;

			expect(joinMemberEvent.getContent().membership).toBe('join');
			expect([...stateAfterAccept.keys()]).toEqual(
				expect.arrayContaining(['m.room.create:', `m.room.member:${username}`, `m.room.member:${invitedUsername}`]),
			);
		});
	});

	describe('rejectInvite', () => {
		it('should reject invite and leave room correctly', async () => {
			const username = '@alice:example.com' as UserID;
			const invitedUsername = '@bob:example.com' as UserID;
			const { roomCreateEvent } = await createRoom(username, 'invite');
			const { roomId } = roomCreateEvent;

			await federationSDK.inviteUserToRoom(invitedUsername, roomId, username);

			const stateBeforeReject = await stateService.getLatestRoomState(roomId);
			const inviteMemberEvent = stateBeforeReject.get(`m.room.member:${invitedUsername}`) as
				| PersistentEventBase<RoomVersion, 'm.room.member'>
				| undefined;

			expect(inviteMemberEvent?.getContent().membership).toBe('invite');

			await federationSDK.rejectInvite(roomId, invitedUsername);

			const stateAfterReject = await stateService.getLatestRoomState(roomId);
			const leaveMemberEvent = stateAfterReject.get(`m.room.member:${invitedUsername}`) as PersistentEventBase<
				RoomVersion,
				'm.room.member'
			>;

			expect(leaveMemberEvent.getContent().membership).toBe('leave');
			expect([...stateAfterReject.keys()]).toEqual(
				expect.arrayContaining(['m.room.create:', `m.room.member:${username}`, `m.room.member:${invitedUsername}`]),
			);
		});
	});
});

import { createLogger } from '@rocket.chat/federation-core';
import { Db, MongoClient, type MongoClientOptions } from 'mongodb';

export class DatabaseConnectionService {
	private client: MongoClient | null = null;

	private db: Db | null = null;

	private connectionPromise: Promise<void> | null = null;

	private readonly logger = createLogger('DatabaseConnectionService');

	constructor(private readonly config: { uri: string; poolSize: number }) {
		this.connect().catch((err) => this.logger.error({ msg: 'Initial database connection failed', err }));
	}

	async getDb(): Promise<Db> {
		if (!this.db) {
			await this.connect();
		}

		if (!this.db) {
			throw new Error('Database connection not established');
		}

		return this.db;
	}

	private async connect(): Promise<void> {
		if (this.connectionPromise) {
			return this.connectionPromise;
		}

		if (this.client && this.db) {
			return;
		}

		this.connectionPromise = new Promise<void>((resolve, reject) => {
			try {
				const dbConfig = this.config;

				const options: MongoClientOptions = {
					maxPoolSize: dbConfig.poolSize,
				};

				this.client = new MongoClient(dbConfig.uri, options);
				this.client.connect();

				const { dbName } = this.client.options;
				if (!dbName) {
					throw new Error("Can't get database name from MongoDB connection string");
				}

				this.db = this.client.db(dbName);
				this.logger.info(`Connected to MongoDB database: ${dbName}`);

				resolve();
			} catch (error: unknown) {
				this.logger.error({ msg: 'Failed to connect to MongoDB', err: error });
				this.connectionPromise = null;
				reject(new Error('Database connection failed'));
			}
		});

		return this.connectionPromise;
	}

	async disconnect(): Promise<void> {
		if (this.client) {
			await this.client.close();
			this.client = null;
			this.db = null;
			this.connectionPromise = null;
			this.logger.info('Disconnected from MongoDB');
		}
	}
}

import { describe, expect, it } from 'bun:test';

import { IncompatibleRoomVersionError } from '@rocket.chat/federation-core';
import type { PduForType, RoomID, RoomVersion, UserID } from '@rocket.chat/federation-room';

import { ProfilesService } from './profiles.service';
import type { StateService } from './state.service';

const roomId = '!room:hs1' as RoomID;
const userId = '@alice:hs2' as UserID;

function buildService(roomVersion: RoomVersion) {
	const membershipEvent = {
		type: 'm.room.member',
		room_id: roomId,
		sender: userId,
		state_key: userId,
		content: { membership: 'join' },
	} as unknown as PduForType<'m.room.member'>;

	// captured so the template's room version can be asserted, not just its shape
	const built: { roomVersion?: RoomVersion } = {};

	const stateService = {
		async getRoomVersion() {
			return roomVersion;
		},
		async getLatestRoomState2() {
			return { isUserInvited: () => true };
		},
		async buildEvent(_event: unknown, version: RoomVersion) {
			built.roomVersion = version;
			return { event: membershipEvent };
		},
	} as unknown as StateService;

	return { service: new ProfilesService(null as never, stateService, null as never), membershipEvent, built };
}

describe('makeJoin', () => {
	it('reports the room version the asking server is missing support for', async () => {
		const { service } = buildService('11');

		// the asking server advertised only up to v10, the room is v11
		const error = await service.makeJoin(roomId, userId, ['10'] as RoomVersion[]).catch((e: IncompatibleRoomVersionError) => e);

		expect(error).toBeInstanceOf(IncompatibleRoomVersionError);
		expect(error.errcode).toBe('M_INCOMPATIBLE_ROOM_VERSION');
		expect(error.status).toBe(400);

		// room_version is required on this errcode, it is how the remote learns what it needs
		expect(error.toJSON()).toEqual({
			errcode: 'M_INCOMPATIBLE_ROOM_VERSION',
			error: 'Your homeserver does not support the features required to join this room',
			room_version: '11',
		});
	});

	it('builds a join template at the room version when the asking server supports it', async () => {
		const { service, membershipEvent, built } = buildService('10');

		await expect(service.makeJoin(roomId, userId, ['9', '10', '11'] as RoomVersion[])).resolves.toEqual({
			room_version: '10',
			event: membershipEvent,
		});

		// the template has to be built at the room's version, not at the default
		expect(built.roomVersion).toBe('10');
	});
});

import { describe, expect, it } from 'bun:test';

import type { EventID, Pdu, PduForType, RoomVersion } from '@rocket.chat/federation-room';

import { EventService } from './event.service';
import type { StateService } from './state.service';
import type { EventRepository } from '../repositories/event.repository';

// a v10-shaped member event: pre-v11 redaction keeps origin/prev_state/membership at the top level,
// and only `membership` out of content
const memberEvent = {
	type: 'm.room.member',
	room_id: '!room:hs1',
	sender: '@alice:hs1',
	state_key: '@alice:hs1',
	depth: 5,
	auth_events: ['$auth1'],
	prev_events: ['$prev1'],
	origin_server_ts: 1732999153019,
	origin: 'hs1',
	prev_state: [],
	membership: 'join',
	content: {
		membership: 'join',
		displayname: 'alice',
		avatar_url: 'mxc://hs1/abc',
	},
	hashes: { sha256: 'irrelevant-to-redaction' },
	signatures: { hs1: { 'ed25519:key': 'sig' } },
	unsigned: { age: 2 },
} as unknown as Pdu;

function buildService(roomVersion: RoomVersion, storedEvent: Pdu) {
	const captured: { eventId?: EventID; event?: Pdu } = {};

	const eventRepository = {
		async findById() {
			return { event: storedEvent };
		},
		async redactEvent(eventId: EventID, redactedEvent: Pdu) {
			captured.eventId = eventId;
			captured.event = redactedEvent;
		},
	} as unknown as EventRepository;

	const stateService = {
		async getRoomVersion() {
			return roomVersion;
		},
	} as unknown as StateService;

	const service = new EventService(
		null as never,
		null as never,
		stateService,
		null as never,
		null as never,
		eventRepository,
		null as never,
		null as never,
	);

	return { service, captured };
}

describe('processRedaction', () => {
	it('keeps the pre-v11 top level fields when redacting in a v10 room', async () => {
		const { service, captured } = buildService('10', memberEvent);

		// before v11 the redaction target is a top level field
		const redaction = {
			type: 'm.room.redaction',
			room_id: '!room:hs1',
			sender: '@alice:hs1',
			depth: 6,
			auth_events: [],
			prev_events: [],
			origin_server_ts: 1732999153020,
			redacts: '$target' as EventID,
			content: {},
		} as unknown as PduForType<'m.room.redaction'>;

		await service.processRedaction(redaction);

		expect(captured.eventId).toBe('$target' as EventID);

		// stripping these would invalidate the signature, which covers the redacted form
		expect(captured.event).toHaveProperty('origin', 'hs1');
		expect(captured.event).toHaveProperty('membership', 'join');
		expect(captured.event).toHaveProperty('prev_state');

		expect(captured.event?.content).toEqual({ membership: 'join' });
	});

	it('drops the pre-v11 top level fields when redacting in a v11 room', async () => {
		const { service, captured } = buildService('11', memberEvent);

		// v11 moved the redaction target into content
		const redaction = {
			type: 'm.room.redaction',
			room_id: '!room:hs1',
			sender: '@alice:hs1',
			depth: 6,
			auth_events: [],
			prev_events: [],
			origin_server_ts: 1732999153020,
			content: { redacts: '$target' as EventID },
		} as unknown as PduForType<'m.room.redaction'>;

		await service.processRedaction(redaction);

		expect(captured.eventId).toBe('$target' as EventID);

		expect(captured.event).not.toHaveProperty('origin');
		expect(captured.event).not.toHaveProperty('membership');
		expect(captured.event).not.toHaveProperty('prev_state');

		expect(captured.event?.content).toEqual({ membership: 'join' });
	});

	it('records what redacted the event', async () => {
		const { service, captured } = buildService('11', memberEvent);

		const redaction = {
			type: 'm.room.redaction',
			room_id: '!room:hs1',
			sender: '@alice:hs1',
			depth: 6,
			auth_events: [],
			prev_events: [],
			origin_server_ts: 1732999153020,
			content: { redacts: '$target' as EventID },
		} as unknown as PduForType<'m.room.redaction'>;

		await service.processRedaction(redaction);

		expect(captured.event?.unsigned).toHaveProperty('redacted_because', redaction);
	});
});
